def calc_max_segment_ratio(height_ft, base_width_ft, frame_height_ft, tie_levels):
    """Calculate maximum segment height/base ratio."""
    if not tie_levels:
        return height_ft / base_width_ft
    segments = []
    prev = 0.0
    for t in tie_levels:
        segments.append(t - prev)
        prev = t
    segments.append(height_ft - prev)
    max_ratio = max(s / base_width_ft for s in segments)
    return max_ratio

